10.3 Использование набора StatefulSet    361

  10.3.1 Создание приложения и образа контейнера
  Вы будете применять приложение kubia, которое вы использовали в каче-
стве отправной точки на протяжении всей книги. Вы расширите его, чтобы
оно позволяло хранить и извлекать одну запись данных на каждом экземпля-
ре модуля.
  Важные фрагменты исходного кода хранилища данных приведены в следую
щем ниже листинге.

  Листинг 10.1. Простое приложение с внутренним состоянием:
  kubia-pet-image/app.js

...
const dataFile = "/var/data/kubia.txt";
...
var handler = function(request, response) {
  if (request.method == 'POST') {                                            При отправке
    var file = fs.createWriteStream(dataFile);                                 запросов POST
    file.on('open', function (fd) {                                               сохранить тело
      request.pipe(file);                                                              запроса в файл
      console.log("New data has been received and stored.");       данных
      response.writeHead(200);
      response.end("Data stored on pod " + os.hostname() + "\n");
    });
  } else {                                                              В запросах GET (и всех
    var data = fileExists(dataFile)                                        других типах запросов)
      ? fs.readFileSync(dataFile, 'utf8')                               возвращать ваш хостнейм
      : "No data posted yet";                                             и содержимое файла
                                                                             данных    response.writeHead(200);                   
    response.write("You've hit " + os.hostname() + "\n");
    response.end("Data stored on this pod: " + data + "\n");
  }
};

var www = http.createServer(handler);
www.listen(8080);

  Всякий раз, когда приложение получает запрос POST, оно записывает дан-
ные, полученные в теле запроса, в файл /var/data/kubia.txt. По запросу GET оно
возвращает хостнейм и сохраненные данные (содержимое файла). Достаточ-
но просто, верно? Это первая версия приложения. Он еще не кластеризовано,
но этого достаточно, чтобы начать. Вы развернете приложение позже в этой
главе.
  Файл Dockerfile для построения образа контейнера показан в следующем
ниже листинге и остался прежним.

374     Глава 10. Ресурсы StatefulSet: развертывание реплицируемых приложений...

   Листинг 10.9. Обнаружение одноранговых модулей в примере приложения:
   kubia-pet-peers-image/app.js

...
const dns = require('dns');

const dataFile = "/var/data/kubia.txt";
const serviceName = "kubia.default.svc.cluster.local";
const port = 8080;
...
var handler = function(request, response) {
  if (request.method == 'POST') {
    ...
  } else {
    response.writeHead(200);
    if (request.url == '/data') {
      var data = fileExists(dataFile)
        ? fs.readFileSync(dataFile, 'utf8')
        : "No data posted yet";
      response.end(data);
    } else {                                                                   Приложение выполняет
      response.write("You've hit " + os.hostname() + "\n");             поиск в DNS для
      response.write("Data stored in the cluster:\n");                   получения ресурсных
      dns.resolveSrv(serviceName, function (err, addresses) {      записей SRV
        if (err) {
          response.end("Could not look up DNS SRV records: " + err);
          return;
        }
        var numResponses = 0;
        if (addresses.length == 0) {
          response.end("No peers discovered.");
        } else {
          addresses.forEach(function (item) {           
            var requestOptions = {                                     Каждый модуль,
              host: item.name,                                                на который указала
                                                                                            запись SRV, после              port: port,
                                                                                                этого адресуется, для              path: '/data'                                                                                                того чтобы получить
            };                                                                           его данные
            httpGet(requestOptions, function (returnedData) { 
              numResponses++;
              response.write("- " + item.name + ": " + returnedData);
              response.write("\n");
              if (numResponses == addresses.length) {
                response.end();
              }
            });

456     Глава 12. Защита сервера API Kubernetes
12.3 Резюме
Эта глава дала вам основополагающее понимание того, как защищать сервер
API Kubernetes. Вы узнали следующее:
  клиентами сервера API могут быть как пользователь-человек, так и ра-
    ботающие в модулях приложения;
  приложения в модулях связаны с учетной записью службы ServiceAcco
      unt;
  пользователи и учетные записи связаны с группами;
  по умолчанию модули запускаются под установленной по умолчанию
     учетной записью, которая автоматически создается для каждого про-
     странства имен;
  дополнительные учетные записи служб могут быть созданы вручную и
     связаны с модулем;
  учетные записи могут быть сконфигурированы, чтобы разрешать мон-
     тирование только ограниченного списка секретов в данном модуле;
  учетная запись также может использоваться для прикрепления к моду-
    лям секретов извлечения образов, поэтому вам не нужно указывать сек
     реты в каждом модуле;
  роли и кластерные роли определяют, какие действия могут выполняться
     на ресурсах;
  привязки ролей RoleBinding и привязки кластерных ролей ClusterRo
      leBinding привязывают роли и кластерные роли к пользователям, груп-
    пам и учетным записям;
  каждый кластер поставляется с набором кластерных ролей, действую-
    щих по умолчанию, и привязок кластерных ролей.
  В следующей главе вы узнаете, как защищать узлы кластера от модулей и
как изолировать модули друг от друга путем обеспечения защиты сети.
